-- SPIN XI — the daily rotation
-- Generated by scripts/build-challenges.mjs. Do not edit by hand.
--
--   546 slots · 13 objectives
--
-- Which challenge a given day gets is slot = days-since-epoch mod 546, so
-- everybody plays the same one without a calendar to keep topped up. The draw
-- itself — which squads you spin — is seeded on the day and is different every
-- day regardless, so this governs the shape of the puzzle, not its content.
--
-- Safe to run on its own, and safe to re-run. It replaces the table's contents
-- and touches nothing else, so the ratings are not recomputed.

begin;

delete from challenges;


-- Any client holding a cached archive must fetch the new rotation.
update dataset_meta set version = gen_random_uuid(), updated_at = now();

commit;
